#!/bin/bash
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

tag="$(git describe --tags --exact-match HEAD 2>/dev/null || true)"
if [[ -n "$tag" ]]; then
  version="${tag#v}"
else
  version="$(git rev-parse --short HEAD)"
fi
output="$ROOT/Sources/Nyathing/Version.swift"
cat > "$output" <<EOF
// Generated by Scripts/generate-version.sh. Do not edit.
enum AppVersion {
  static let current = "$version"
}
EOF
